get_header();$members=class_exists('StageArtCore\\Domain\\Member\\MemberRepository')?(new StageArtCore\Domain\Member\MemberRepository())->all(true):[];?><main class="stageart-container stageart-page"><header class="stageart-page-header"><p class="stageart-kicker">Members</p><h1><?php echo esc_html(get_the_title());?></h1></header><?php if($members):?><div class="stageart-members"><?php foreach($members as $m):?><article class="stageart-card"><a class="stageart-card-link" href="<?php echo esc_url(home_url('/member/'.rawurlencode((string)$m['slug']).'/'));?>"><?php if(!empty($m['photo_id'])):?><div class="stageart-member-card-image"><?php echo wp_get_attachment_image((int)$m['photo_id'],'medium');?></div><?php else:?><div class="stageart-member-card-image"></div><?php endif;?><div class="stageart-member-card-body"><h2><?php echo esc_html((string)$m['name']);?></h2><?php if(!empty($m['roles'])):?><p class="stageart-member-card-roles"><?php echo esc_html(implode(' / ',array_map(static fn($r)=>StageArtCore\Domain\Member\MemberRepository::ROLES[$r]??$r,$m['roles'])));?></p><?php endif;?></div></a></article><?php endforeach;?></div><?php else:?><p class="stageart-placeholder">現在公開されているメンバーはいません。</p><?php endif;?></main><?php get_footer();?>
